                  const _fcs = Storage.getSettings();
                  _fcs.finGoodColor         = document.getElementById('tcm-fin-good-color')?.value         || '#b6d7a8';
                  _fcs.finBadColor          = document.getElementById('tcm-fin-bad-color')?.value          || '#ea9999';
                  Storage.saveSettings(_fcs);
