          // ── Determine next employee to train based on current TCM mode ──
          function getNextEmpId() {
              const s = Storage.getSettings();
              const mode = s.rotationMode || 'priority';
              const state = UI.state;
              if (!state) return null;

              const { employees, directorId } = state;
              const _tornDayStartMs = Storage.tornDayStart();
              const todayLog        = Storage.getTrainedLog();
              const nonDirIds = Object.keys(employees || {}).filter(id =>
                  employees[id].position !== 'Director' && String(id) !== String(directorId || '')
              );

              // ── CONTRACT + ROTATIONAL: buyers first, then rotate the rest ──
  if (mode === 'contract_rotational') {
                  const _crRot0 = Storage.getRotation();
                  const _crExcl0 = new Set(_crRot0.excluded || []);
                 const _crSales = Storage.getTrainSales().filter(c =>
                  c.active !== false && employees[c.buyerEmpId]
                  && !_crExcl0.has(c.buyerEmpId)
              ).filter(c => {
                  // Skip fully completed contracts
                  const _cl = (Storage.getTrainedLog()[c.buyerEmpId] || [])
                      .filter(e => e.ts && e.date >= (c.startDate || ''));
                  const _cs2 = new Set();
                  return _cl.filter(e => { if (_cs2.has(e.ts)) return false; _cs2.add(e.ts); return true; }).length < c.totalTrains;
              });
              for (const _crS of _crSales) {
                  const _crDone = (todayLog[_crS.buyerEmpId] || []).filter(e => e.ts && e.ts >= _tornDayStartMs).length;
                  const _dailyLimit = _crS.dailyReservation || 0;
                  const _dailyOk = _dailyLimit === 0 ? (_crDone === 0) : (_crDone < _dailyLimit);
                  if (_dailyOk && !_inFlightTrains.has(String(_crS.buyerEmpId))) return _crS.buyerEmpId;
              }
                  // All contract buyers are done for today — fall through to normal rotation
                  const _crReserved = _crSales.reduce((sum, c) => sum + (c.dailyReservation || 0), 0);
                  const _crBudget = Math.max(0, (state.detailed?.trains_available ?? 0) - _crReserved);
                  const _crQueue = Storage.getTrainQueue(employees, _crBudget, 'rotational', directorId, state.todayNews, state.typeName);
                  const _crNext = _crQueue.today.find(e => !e.done && e.scheduled);
                  return _crNext?.empId || null;
              }

// ── MANUAL mode: use template ──
              if (s.templateModeEnabled) {
                  const dow         = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][new Date().getDay()];
                  const todayStr    = new Date().toISOString().slice(0, 10);
                  const lockedToday = Storage.getManualScheduleLog()[todayStr];
                  const todayTmpl   = lockedToday || Storage.getWeeklyTemplate()[dow] || {};
                  // Find first employee who hasn't hit their planned count today
                  for (const id of nonDirIds) {
                      const planned = todayTmpl[id] || 0;
                      if (!planned) continue;
                      const done = (todayLog[id] || []).filter(e => e.date === todayStr && e.ts).length;
                      if (done < planned) return id;
                  }
                  return null; // all done for today per template
              }

              // ── PRIORITY mode ──
              if (mode === 'priority') {
                  // Among employees NOT yet trained to their planned count today, sort by tier distance
                  const _prPositions2 = CompanyData.positions(state.typeName);
                  let _prTrainerBonus = 0;
                  for (const _prEmpX of Object.values(employees || {})) {
                      const _prResX = PosNorm.resolve(_prEmpX.position, _prPositions2);
                      if (_prResX?.data?.special === 'trainer') {
                          const _prEffX = _prEmpX.effectiveness?.working_stats || 0;
                          if (_prEffX >= TCM.EE_TIER_4) _prTrainerBonus += 3;
                          else if (_prEffX >= TCM.EE_TIER_3) _prTrainerBonus += 2;
                          else if (_prEffX >= TCM.EE_TIER_2) _prTrainerBonus += 1;
                      }
                  }
                  const _prBudget = Math.min(20, state.profile?.rating || 0) + _prTrainerBonus;
                  const _prQueue = Storage.getTrainQueue(employees, _prBudget, 'priority', directorId, state.todayNews, state.typeName);
                  const _prNext = _prQueue.today.find(e => !e.done && e.scheduled && !_inFlightTrains.has(String(e.empId)));
                  if (_prNext) return _prNext.empId;
                  // Fallback: closest to next tier among anyone not done
                  const sorted = nonDirIds.map(id => {
                      const emp = employees[id];
                      const totalEff = emp?.effectiveness?.total || emp?.effectiveness?.working_stats || 0;
                      const nextTier = [50, 100, 150, 200].find(t => t > totalEff);
                      const todayDone = (todayLog[id] || []).filter(e => e.date === today && e.ts).length;
                      return { id, dist: nextTier ? nextTier - totalEff : 999, todayDone };
                  }).sort((a, b) => a.dist - b.dist || a.todayDone - b.todayDone);
                  return sorted[0]?.id || null;
              }

              // ── ROTATIONAL mode — delegate to getTrainQueue for consistency with Today tab ──
              const _gnPositions = CompanyData.positions(state.typeName);
              let _gnTrainerBonus = 0;
              for (const _gnEmp of Object.values(employees || {})) {
                  const _gnRes = PosNorm.resolve(_gnEmp.position, _gnPositions);
                  if (_gnRes?.data?.special === 'trainer') {
                      const _gnEff = _gnEmp.effectiveness?.working_stats || 0;
                      if (_gnEff >= TCM.EE_TIER_4) _gnTrainerBonus += 3;
                      else if (_gnEff >= TCM.EE_TIER_3) _gnTrainerBonus += 2;
                      else if (_gnEff >= TCM.EE_TIER_2) _gnTrainerBonus += 1;
                  }
              }
              const _gnStars = state.profile?.rating || 0;
              const _gnRawBudget = Math.min(20, _gnStars) + _gnTrainerBonus;
              const _gnTrainsAvail = state.detailed?.trains_available ?? null;
              const _gnEffBudget = (_gnTrainsAvail !== null && _gnTrainsAvail > _gnRawBudget) ? _gnTrainsAvail : _gnRawBudget;
              const _gnReserved = Storage.getTrainSales()
                  .filter(c => c.active !== false && (c.dailyReservation || 0) > 0 && employees[c.buyerEmpId])
                  .reduce((s, c) => s + (c.dailyReservation || 0), 0);
              const _gnRotBudget = Math.max(0, _gnEffBudget - _gnReserved);
              const _gnQueue = Storage.getTrainQueue(employees, _gnRotBudget, mode, directorId, state.todayNews, state.typeName);
              const _gnNext = _gnQueue.today.find(e => !e.done && e.scheduled);
              return _gnNext?.empId || null;
          }

