                      const _sLi   = document.querySelector(`li[data-user="${cur.empId}"]`);
                      const _sRs   = _sLi?.querySelector('select.employee-rank');
                      const _sUd   = _sLi?.querySelector('.update');
                      const _sUb   = _sUd?.querySelector('button');
