                  // ── Position-swap: helpers ────────────────────────────────────
                  function _psBestPosForStat(stat, empId) {
              const _typeName = UI.state?.typeName;
              if (!_typeName || !stat) return null;
              const _positions = CompanyData.positions(_typeName);
              if (!_positions) return null;
              const _candidates = [];
              for (const [name, data] of Object.entries(_positions)) {
                  if (data.primary !== stat) continue;
                  _candidates.push({ name, gain: data.priGain, req: data.priReq });
              }
              if (!_candidates.length) return null;
              // Highest gain first. Within 10% gain difference, prefer lower stat requirement.
              _candidates.sort((a, b) => {
                  const _pct = Math.abs(a.gain - b.gain) / Math.max(a.gain, b.gain, 1);
                  if (_pct > 0.10) return b.gain - a.gain;
                  return a.req - b.req;
              });
              return _candidates[0]?.name || null;
          }

